import{_ as t,o,c as a,a2 as r}from"./chunks/framework.B_GyVC5q.js";const u=JSON.parse('{"title":"Release notes","description":"","frontmatter":{"title":"Release notes"},"headers":[],"relativePath":"release-notes/en.md","filePath":"release-notes/en.md"}'),s={name:"release-notes/en.md"};function i(n,e,l,d,c,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="release-notes" tabindex="-1">Release notes <a class="header-anchor" href="#release-notes" aria-label="Permalink to &quot;Release notes&quot;">​</a></h1><hr><h2 id="_1-5-x" tabindex="-1">1.5.x <a class="header-anchor" href="#_1-5-x" aria-label="Permalink to &quot;1.5.x&quot;">​</a></h2><h3 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h3><p>Version <code>1.5.x</code> adds <strong>Flows</strong> (visual canvas for data/request pipelines with run/debug, templates, library, import/export, and Flows AI); <strong>Generate zip</strong> / <strong>Repeat each</strong> for fast parent–child seeds; local SVG logos and portraits; Flows AI that <strong>builds and optimizes</strong> graphs; adds <strong>AI actions &amp; tasks</strong> (dataclass Generate data / Ask dataclass with footer history); adds <strong>Relations</strong> (orbit canvas for many-to-one links, make center, unlink, history, and duplicate-with-select); adds <strong>query plan &amp; path</strong>, <strong>Copy as</strong>, desktop <strong>Copy session</strong>, <strong>image zoom</strong>, <strong>Docker</strong> hosting, environment <strong>template playground</strong>, and entity-form upgrades (boolean fields, upload field, empty-before-insert); and polishes anonymize limits/preview, catalog counts/reload, online status, relation-key handling, mobile keyboard, console log filters, verbose flow logs (including collapse all), compact toasts, and desktop link handling.</p><h3 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h3><h4 id="flows" tabindex="-1">Flows <a class="header-anchor" href="#flows" aria-label="Permalink to &quot;Flows&quot;">​</a></h4><ul><li><strong>Flows workspace</strong> — Open from the footer <strong>Flows</strong> control, the command palette (<strong>Flows</strong>), or the welcome screen. Build pipelines on a canvas with Start/End anchors, a block palette, outline, and inspector.</li><li><strong>Library</strong> — Save flows per database; search, duplicate, delete, clear all; import / export / copy JSON.</li><li><strong>Templates</strong> — Start from Operators tour, Operators · Combine / Accumulate / Slice, Evaluate &amp; logic, Query data, HTTP · Ping <code>$info</code>, or Trusted files.</li><li><strong>Data &amp; network blocks</strong> — List (multi-dataclass), Create, Generate, Update, Purge (query / entity set / full dataclass), CSV import, HTTP, and Method (catalog / singleton / dataclass / entity).</li><li><strong>Input blocks</strong> — Inject a payload (including <code>$faker</code> numbers), Interval ticks (<code>{ counter, timestamp }</code>), and Timestamp sources that fire when the run starts (no inbound wire).</li><li><strong>Code &amp; logic</strong> — Set variables, Evaluate (sandboxed TypeScript <code>main()</code>), If / For / <strong>Repeat each</strong> / Delay, Log, Timing timeline, Note (Markdown, skipped at run), and AI prompt blocks.</li><li><strong>Stream operators</strong> — RxJS-style Map, Filter, Take, Merge, ForkJoin, Buffer, Debounce, and related operators for pipeline composition. Palette and canvas tooltips link to the official RxJS docs for named operators.</li><li><strong>Run &amp; debug</strong> — Run, pause/resume, stop, step over; per-block breakpoints with global enable/disable; follow the current step on the canvas; run log, watches, and evaluate-at-breakpoint console.</li><li><strong>Verbose run log</strong> — Optional <strong>Verbose</strong> next to dry run. Each block logs pending then done (or error) with duration, inputs, and outputs you can expand (same object tree as the Console). Duration and copy sit next to the line text. <strong>Collapse all</strong> (toolbar, overflow menu, or log context menu) folds expanded rows and object trees without clearing the log.</li><li><strong>Note blocks</strong> — Markdown notes are documentation only: they are skipped at run time and cannot be disabled or take a breakpoint.</li><li><strong>Run on server</strong> — When the base exposes <code>FlowRunner</code> and the flow has no client-only nodes; trusted-folder flows still require desktop or mobile.</li><li><strong>Flows AI</strong> — Dock chat to <strong>create optimized flows</strong> from a prompt and <strong>refactor</strong> the current graph (batched generate, zip FKs, repeatEach). Starter prompts include <strong>Optimize for speed</strong>. Configure an LLM in Settings.</li><li><strong>Generate zip</strong> — Sequential FKs: row <code>i</code> copies <code>entities[i]</code> from a previous generate (<code>from</code> path such as <code>nodes.addr.stdout.entities</code>, <code>attr</code> default <code>ID</code>). Count follows the parent list. Prefer this over <code>$pick</code> when each parent must get a guaranteed number of children.</li><li><strong>Repeat each</strong> — Logic block that repeats each inbound entity N times (literal or <code>{{$faker.number.int | between:10,50}}</code> per parent). Pair with Generate zip for “10–50 employees per company” without a <code>for</code> + create loop.</li><li><strong>Per-row faker on Generate</strong> — <code>$faker</code> / <code>$pick</code> field templates stay unresolved until each entity is created, so names, addresses, and media differ across the batch (createMany).</li><li><strong>Local SVG logos and portraits</strong> — <code>{{$faker.company.logo}}</code> and <code>{{$faker.image.personPortrait}}</code> resolve to compact SVG data URIs (optional <code>female</code> / <code>male</code> on portraits). No CDN fetch before <code>$upload</code>.</li><li><strong>CSV &amp; relations</strong> — dataInit-style CSV imports with <code>$rel_*</code> relation columns, dependency-ordered waves, and optional skip-when-not-empty.</li><li><strong>Catalog-aware AI fields</strong> — Remap AI field keys onto real catalog attributes; fill related-entity foreign keys from <code>{{item.__KEY}}</code> when generating linked rows.</li></ul><h4 id="ai-actions-tasks" tabindex="-1">AI actions &amp; tasks <a class="header-anchor" href="#ai-actions-tasks" aria-label="Permalink to &quot;AI actions &amp; tasks&quot;">​</a></h4><ul><li><strong>AI actions menu</strong> — On dataclass lists, sidebar rows, and the structure graph: <strong>Generate data</strong>, <strong>Ask dataclass</strong>, and generate filter/params (requires LLM).</li><li><strong>AI tasks</strong> — Footer history for background runs; cancel one or all; confirmation dialogs for destructive steps; activity/trace inspection.</li></ul><h4 id="query-requests" tabindex="-1">Query &amp; requests <a class="header-anchor" href="#query-requests" aria-label="Permalink to &quot;Query &amp; requests&quot;">​</a></h4><ul><li><strong>Query plan &amp; path</strong> — Toggle <code>$queryplan</code> / <code>$querypath</code> in the Query Builder, HTTP Client, and Method Executor; inspect index vs sequential access, joins, timings, and JSON.</li><li><strong>Copy as</strong> — Copy the current or console network request as runnable code (4D <code>HTTPRequest</code>, cURL, JavaScript, Python, and other targets).</li></ul><h4 id="desktop-hosting" tabindex="-1">Desktop &amp; hosting <a class="header-anchor" href="#desktop-hosting" aria-label="Permalink to &quot;Desktop &amp; hosting&quot;">​</a></h4><ul><li><strong>Copy session</strong> — Sign in via browser on the connection screen; confirm to send session cookies into the desktop app (install the downloadable <code>CopySession</code> class).</li><li><strong>Docker</strong> — Run the published image or build from <code>DataExplorer.zip</code> with <code>BACKEND_URL</code> (see Getting started).</li><li><strong>Desktop zoom</strong> — View menu Zoom In / Out / Reset.</li></ul><h4 id="environments-templates" tabindex="-1">Environments &amp; templates <a class="header-anchor" href="#environments-templates" aria-label="Permalink to &quot;Environments &amp; templates&quot;">​</a></h4><ul><li><strong>Template playground</strong> — Environment switcher → <strong>Test…</strong> to evaluate templates, <code>$faker</code>, filters, and <code>$this</code> with examples.</li><li><strong>Pipe filters</strong> — Additional transforms including <code>capitalize</code>, <code>title</code>, trim variants, <code>take_before</code> / <code>take_after</code>, <code>remove</code> / <code>replace</code>, padding, and <code>default</code>.</li></ul><h4 id="entity-forms-media" tabindex="-1">Entity forms &amp; media <a class="header-anchor" href="#entity-forms-media" aria-label="Permalink to &quot;Entity forms &amp; media&quot;">​</a></h4><ul><li><strong>Boolean fields</strong> — Checkbox and bool-or-template editing for boolean attributes.</li><li><strong>Upload field</strong> — Image/blob fields with file pick, drag/drop, trusted-folder templates, and clear upload state.</li><li><strong>Empty before insert</strong> — Optionally delete all entities in the dataclass before batch create (confirmed).</li><li><strong>Media upload concurrency</strong> — Parallel, cached media materialization for multi-entity create, anonymize, and flows.</li><li><strong>Treat relation key 0 as empty</strong> — Settings option so deferred relations with key <code>0</code> show as empty instead of loading.</li></ul><h4 id="relations" tabindex="-1">Relations <a class="header-anchor" href="#relations" aria-label="Permalink to &quot;Relations&quot;">​</a></h4><ul><li><strong>Relations canvas</strong> — Explore a record’s many-to-one links on an orbit graph (center + ring). Open from the command palette (<strong>Relations</strong>), entity cards or table <strong>⋯</strong> menu, entity viewer, or terminal entity cells.</li><li><strong>Select vs Make center</strong> — Click a linked record to inspect it in the details panel without recentering; <strong>Make center</strong> expands that record’s N:1 neighborhood and recenters the canvas.</li><li><strong>Spokes &amp; unlink</strong> — Click a relation spoke for edge details; <strong>Unlink</strong> clears the foreign key (with confirmation) without deleting the related record.</li><li><strong>History &amp; zoom</strong> — Back/forward selection history; zoom in, out, and fit (toolbar, mouse wheel, or ⌘/Ctrl +/− / 0 when the canvas is focused).</li><li><strong>Duplicate</strong> — Confirm before duplicating a record onto the canvas; a success toast offers <strong>Select</strong> to focus the new record as the orbit center.</li><li><strong>Row actions</strong> — Entity list and card actions use a single <strong>⋯</strong> overflow menu (Relations, copy JSON, duplicate, delete).</li></ul><h4 id="selection-tools-media-ux" tabindex="-1">Selection tools &amp; media UX <a class="header-anchor" href="#selection-tools-media-ux" aria-label="Permalink to &quot;Selection tools &amp; media UX&quot;">​</a></h4><ul><li><strong>Anonymize limit &amp; preview</strong> — Cap how many entities to anonymize; see limit vs entity-set vs dataclass totals; richer preview before run.</li><li><strong>Image zoom</strong> — Open pictures in a zoomable, pannable preview (+ / − / 0, wheel, drag).</li></ul><h4 id="catalog-connectivity" tabindex="-1">Catalog &amp; connectivity <a class="header-anchor" href="#catalog-connectivity" aria-label="Permalink to &quot;Catalog &amp; connectivity&quot;">​</a></h4><ul><li><strong>Dataclass counts</strong> — Load entity counts on demand (auto when the catalog is small) for Home totals and charts.</li><li><strong>Reload catalog</strong> — Clear cache and reload from empty / error states.</li><li><strong>Online status</strong> — Footer offline indicator; cloud AI and updates pause while LAN REST and local LLMs stay available.</li><li><strong>Console log filter</strong> — Multi-select levels (log, info, warn, error, network) with a tri-state <strong>All logs</strong> control.</li><li><strong>Log retention</strong> — Flow logs limit and Console limit: <code>0</code> keeps every entry until you clear the log.</li><li><strong>Console remove entry</strong> — Delete individual console or network log lines.</li><li><strong>Reset selection</strong> — Running a new query clears the previous multi-selection so results stay in sync.</li><li><strong>Compact toasts</strong> — Success and error toasts are denser, with inline actions beside the title when needed.</li></ul><h3 id="docs" tabindex="-1">Docs <a class="header-anchor" href="#docs" aria-label="Permalink to &quot;Docs&quot;">​</a></h3><ul><li>Guide pages for <a href="https://midrissi.github.io/4d-dataexplorer/guide/flows.html" target="_blank" rel="noreferrer">Flows</a> (Generate zip, Repeat each, verbose log, collapse all, Notes, RxJS docs), <a href="https://midrissi.github.io/4d-dataexplorer/guide/console.html" target="_blank" rel="noreferrer">Console</a> (log-level filter), <a href="https://midrissi.github.io/4d-dataexplorer/guide/trusted-folders.html" target="_blank" rel="noreferrer">Trusted folders</a> (icon grid), <a href="https://midrissi.github.io/4d-dataexplorer/guide/ai-actions.html" target="_blank" rel="noreferrer">AI actions &amp; tasks</a>, <a href="https://midrissi.github.io/4d-dataexplorer/guide/getting-started.html#run-with-docker" target="_blank" rel="noreferrer">Docker</a>, query plan (Query builder / HTTP Client / Method Executor), Copy as, and Copy session (macOS desktop).</li></ul><h3 id="fixes" tabindex="-1">Fixes <a class="header-anchor" href="#fixes" aria-label="Permalink to &quot;Fixes&quot;">​</a></h3><ul><li><strong>Generate uniqueness</strong> — Generate no longer stamps one resolved faker value onto every cloned row.</li><li><strong>Portrait templates</strong> — <code>$faker.image.personPortrait</code> no longer depends on a remote image URL.</li><li><strong>Mobile soft keyboard</strong> — Editors stay above the on-screen keyboard so inputs remain visible while typing.</li><li><strong>Console with many images</strong> — Trusted-folder thumbnails no longer flood the console; icon view stays virtualized so large folders do not stall the UI.</li><li><strong>Icon grid overlap</strong> — Trusted-folder icon tiles keep a fixed thumbnail height, wrap filenames without splitting the extension, and show the type as a muted badge under the name (not on the image).</li><li><strong>Desktop page zoom</strong> — ⌘/Ctrl + trackpad inertia no longer zooms after you release the modifier; zoom only applies while the gesture started with ⌘ or Ctrl.</li><li><strong>Desktop external links</strong> — <code>https</code> / <code>http</code> / <code>mailto</code> links (including RxJS docs in operator tooltips) open once in the system browser. Rebuild the desktop app so opener permissions apply.</li></ul><h2 id="_1-4-x" tabindex="-1">1.4.x <a class="header-anchor" href="#_1-4-x" aria-label="Permalink to &quot;1.4.x&quot;">​</a></h2><h3 id="overview-1" tabindex="-1">Overview <a class="header-anchor" href="#overview-1" aria-label="Permalink to &quot;Overview&quot;">​</a></h3><p>Version <code>1.4.x</code> adds <strong>environment variables</strong> (globals, profile, and database layers with <code>{{templates}}</code>, pipe filters, and Faker-powered dynamics); adds <strong>trusted folders</strong> on desktop and mobile (<code>{{$files.alias}}</code> templates for 4D <code>$upload</code>); adds the <strong>ORDA Terminal</strong> (REPL and Code modes with snippet files) in a shared bottom dock with the Console; adds <strong>REST Export</strong> (Collection v2.1 and OpenAPI 3.1 from the catalog, HTTP Client, and Method Executor); adds <strong>Selection tools</strong> (analyze with <code>$distinct</code> / <code>$compute</code>, multi-format export/import, and Faker anonymize with download, import-as-new, or in-place update); adds <strong>favourites</strong> for HTTP Client and Method Executor; ships <strong>iOS and Android</strong> mobile apps; improves Method Executor (Advanced params/headers, default <code>$method=entityset</code>, result-panel errors, empty states, and mod-click tab shortcuts); improves console network logging (pending request body, open while pending, cancel); and polishes mobile HTTP Client and dock UX.</p><h3 id="features-1" tabindex="-1">Features <a class="header-anchor" href="#features-1" aria-label="Permalink to &quot;Features&quot;">​</a></h3><h4 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment variables&quot;">​</a></h4><ul><li><strong>Environments editor</strong> — Manage <strong>Globals</strong>, <strong>Profile</strong>, and <strong>This database</strong> scopes from Tools, the command palette (<strong>Environments</strong>), or the footer <strong>Environment</strong> switcher → <strong>Manage…</strong>.</li><li><strong>Active environments</strong> — One profile and one database environment active at a time; footer switcher selects them and previews the merged variable list (secrets stay masked until revealed).</li><li><strong>Templates</strong> — Insert <code>{{name}}</code> in HTTP Client, Method Executor, Query Builder, Create Entity, ORDA Terminal snippets, and other templated fields; values resolve at send/run time.</li><li><strong>Pipe filters</strong> — Liquid-style transforms (<code>upper</code>, <code>lower</code>, <code>replace</code>, <code>unwrap</code>, <code>substring</code>, <code>hash:md5</code>, …) plus generator options (<code>female</code> / <code>male</code>, <code>min</code> / <code>max</code> / <code>between</code>, <code>after</code> / <code>before</code>).</li><li><strong><code>$this</code> context</strong> — Call-site object access (<code>{{$this.firstName}}</code>, <code>{{$this.headers.Authorization}}</code>, <code>{{$this.methodName}}</code>, …) for entity forms, HTTP Client, Method Executor, and Query Builder; multi-pass sibling resolve.</li><li><strong>Dynamic variables</strong> — Full Faker surface via <code>{{$faker.module.method}}</code> (e.g. <code>{{$faker.person.fullName}}</code>, <code>{{$faker.string.uuid}}</code>), plus clock aliases <code>{{$timestamp}}</code> / <code>{{$isoTimestamp}}</code>.</li><li><strong>Helper templates</strong> — <code>$pick</code> / <code>$sample</code> / <code>$unique</code> / <code>$repeat</code> / <code>$object</code> / <code>$vector</code> (and <code>$faker.helpers.*</code>) for lists, JSON objects, and embedding-style float arrays; <code>count:n</code>, <code>count:min,max</code>, or <code>count:&gt;=n</code> / <code>count:&lt;=n</code> for dynamic array length; <code>$vector | dims:n</code> (optional <code>normalize</code>); deep resolve rehydrates exact structured leaves.</li><li><strong>Named Lists</strong> — Define global, profile, or database-scoped hardcoded or dataclass-backed <code>$lists.name</code> sources; manage them from the footer <strong>Lists</strong> switcher and reuse their values in <code>$pick</code>, <code>$sample</code>, and <code>$unique</code> templates.</li><li><strong>Chips &amp; autocomplete</strong> — Known variables highlight as chips; completions cover environment keys, aliases, helpers, and <code>$faker.*</code> paths; unresolved keys stay visible as <code>{{…}}</code>.</li><li><strong>Export / Import</strong> — Share environments as JSON from the editor toolbar.</li><li><strong>Terminal API</strong> — <code>app.environment</code> helpers plus <code>.env</code> / <code>.envs</code> dot commands.</li></ul><h4 id="trusted-folders" tabindex="-1">Trusted folders <a class="header-anchor" href="#trusted-folders" aria-label="Permalink to &quot;Trusted folders&quot;">​</a></h4><ul><li><strong>Device allowlist</strong> — On desktop and mobile, add local folders (Home, Desktop, Documents, or Downloads) with an alias. Aliases stay on this device and are not part of profile export.</li><li><strong>$files templates</strong> — <code>{{$files.photos}}</code> picks a random file, <code>{{$files.photos/cat.jpg}}</code> a specific path, and <code>{{$files.photos/**/*.png}}</code> a glob match; optional <code>| ext:</code> and <code>| recursive:false</code>.</li><li><strong>File manager</strong> — List or icon view, resizable sidebar and preview, image preview, and persisted selection / expanded folders.</li><li><strong>Copy templates</strong> — Preview actions copy <code>$files</code> tokens with a click-to-copy tooltip that becomes Copied.</li><li><strong>Confirm remove</strong> — Removing a trusted folder asks for confirmation; files on disk are not deleted.</li><li><strong>Keyboard navigation</strong> — Arrow keys, Home/End, Enter, and Backspace in the explorer; ↓ from the filter field focuses the list.</li></ul><h4 id="orda-terminal" tabindex="-1">ORDA Terminal <a class="header-anchor" href="#orda-terminal" aria-label="Permalink to &quot;ORDA Terminal&quot;">​</a></h4><ul><li><strong>Bottom dock</strong> — Console and Terminal share a resizable dock with a tab strip; open state and active tab persist per profile.</li><li><strong>REPL</strong> — Run <code>ds.*</code> expressions with Monaco highlighting, catalog-aware autocomplete (including inside <code>query(&quot;…&quot;)</code>), and ↑/↓ history.</li><li><strong>Code mode</strong> — Edit named <code>.js</code> snippet files inline; Enter for newline, Shift+Enter (or Run) to execute; <code>⌘/Ctrl+Enter</code> always runs.</li><li><strong>Snippet pack</strong> — Export/import gzip packs (<code>.orda-snippets.gz</code>); <code>.load</code> / <code>.run</code> / <code>.rm</code> with name completion.</li><li><strong>Result cells</strong> — Entities and selections open in tabs; binaries/images use existing viewers; REST traffic appears in Console → Network.</li><li><strong>Dot commands</strong> — <code>.help</code>, <code>.exit</code>, and related commands; compact help rendering.</li></ul><h4 id="rest-export" tabindex="-1">REST Export <a class="header-anchor" href="#rest-export" aria-label="Permalink to &quot;REST Export&quot;">​</a></h4><ul><li><strong>REST Export tab</strong> — Open from Tools or the command palette; a four-step wizard (selection → categories → variables → preview) builds a Collection v2.1 or OpenAPI 3.1 toolkit from the live catalog.</li><li><strong>Request catalog</strong> — Auth, catalog, info, CRUD, entity sets, dataclass / entity / entitySelection functions, and singletons. Unexposed methods and directory login are off by default.</li><li><strong>Preview</strong> — Expand or collapse folders (including expand / collapse all), turn emojis on or off, Shift-click to apply or clear emojis by category, and optionally attach official 4D REST documentation to each request.</li><li><strong>HTTP Client &amp; Method Executor</strong> — Export the current request or favourites as a collection or OpenAPI as well.</li></ul><h4 id="mobile" tabindex="-1">Mobile <a class="header-anchor" href="#mobile" aria-label="Permalink to &quot;Mobile&quot;">​</a></h4><ul><li><strong>iOS &amp; Android apps</strong> — Native shells with connection profiles, CORS-free HTTP, and safe-area layouts.</li><li><strong>Touch dock</strong> — Console/Terminal as overlays with larger hit targets; share sheet / Downloads for exports.</li><li><strong>Mobile CI</strong> — GitHub Actions builds and uploads mobile release artifacts (including Android signing support).</li></ul><h4 id="method-executor" tabindex="-1">Method Executor <a class="header-anchor" href="#method-executor" aria-label="Permalink to &quot;Method Executor&quot;">​</a></h4><ul><li><strong>Advanced params &amp; headers</strong> — Params and Headers use the same underline tab editor as the HTTP Client; default query param <code>$method=entityset</code> is seeded for new method runs (UI is the source of truth for <code>$method</code>).</li><li><strong>Result-panel errors</strong> — Execution, network, and cancel errors appear in the result panel (status + error body), matching HTTP Client behaviour; validation messages stay under the config pane.</li><li><strong>Empty states</strong> — Clear “select a method” guidance in the config and result panes until a method is chosen; Execute stays outline-disabled until then.</li><li><strong>Mod-click shortcuts</strong> — <code>⌘/Ctrl+click</code> opens a Method Executor tab in the background; <code>⌘/Ctrl+Shift+click</code> opens the call in the HTTP Client (method list, favourites, history, and method picker).</li></ul><h4 id="console-media" tabindex="-1">Console &amp; media <a class="header-anchor" href="#console-media" aria-label="Permalink to &quot;Console &amp; media&quot;">​</a></h4><ul><li><strong>Network image preview</strong> — Inline preview for image responses in the console network log.</li><li><strong>Pending requests</strong> — Request body is published as soon as the call starts; <strong>Open in HTTP Client</strong> is available while the entry is still pending.</li><li><strong>Cancel in-flight requests</strong> — Abort pending network calls from the console when supported.</li><li><strong>Share / save</strong> — Share or download binary objects and images via platform-native paths (fixes iOS WKWebView download failures).</li></ul><h4 id="favourites-create-flows" tabindex="-1">Favourites &amp; create flows <a class="header-anchor" href="#favourites-create-flows" aria-label="Permalink to &quot;Favourites &amp; create flows&quot;">​</a></h4><ul><li><strong>HTTP Client favourites</strong> — Save, reopen, and export favourites (including collection / OpenAPI export).</li><li><strong>Method Executor favourites</strong> — Same favourites workflow for method calls.</li><li><strong>Batch create entity</strong> — Create multiple entities with templated field values resolved from the active environment map.</li></ul><h4 id="selection-tools" tabindex="-1">Selection tools <a class="header-anchor" href="#selection-tools" aria-label="Permalink to &quot;Selection tools&quot;">​</a></h4><ul><li><strong>Entry points</strong> — Selection tools menu on dataclass lists, tab context menus, Method Executor selection results, related entity sets, Home entity-set rows, and the command palette.</li><li><strong>Analyze</strong> — Distinct values (<code>$distinct</code>) and compute cards (<code>$compute=$all</code>) for one attribute on the current entity set.</li><li><strong>Export / Import</strong> — Extendable formats (JSON, JSON REST, JSONL, CSV, TSV, SQL, XML, YAML, Markdown, HTML); import creates or updates records in the open dataclass.</li><li><strong>Anonymize</strong> — Field mapping with Faker templates (including <code>|</code> filters), fixed values, keep, or empty; remove fields from the plan so they are omitted from payloads; optional seed; HTTP Client–style preview with auto-detected view mode.</li><li><strong>Image anonymization</strong> — Writable Image attributes accept Faker image templates such as <code>{{$faker.image.personPortrait | female}}</code>; generated portraits are fetched, uploaded through <code>$upload?$rawPict=true</code>, and replaced by 4D upload IDs before export or write actions.</li><li><strong>Anonymize actions</strong> — Download anonymized data, import as new records, or overwrite mapped fields on the current entity set (confirmed; <code>__KEY</code> / <code>__STAMP</code> plus changed fields only); progress covers fetch, Faker generation, parallel image uploads, and finalization, with cancellation while work is still pending.</li></ul><h4 id="ux" tabindex="-1">UX <a class="header-anchor" href="#ux" aria-label="Permalink to &quot;UX&quot;">​</a></h4><ul><li><strong>About dialog</strong> — App about information from mobile/desktop chrome.</li><li><strong>Panel heights</strong> — Entity list and request panes remember height; console height clamps safely when the viewport size is unknown.</li><li><strong>HTTP Client (mobile)</strong> — Responsive request/response summary for narrow screens.</li><li><strong>HTTP binary uploads</strong> — Binary-body pickers accept browser and desktop-native drag/drop, infer the selected file’s <code>Content-Type</code>, and suggest <code>/rest/$upload?$rawPict=true</code> / <code>$binary=true</code> endpoints; Content-Type values autocomplete common MIME types.</li><li><strong>HTTP Client notifications</strong> — Responses containing <code>__WEBFORM.__NOTIFICATION</code> display the same typed notification alert and privilege stamp as Method Executor results.</li><li><strong>Console URL decoding</strong> — Optional toggle to decode percent-encoded URLs in the network log for easier reading.</li><li><strong>Environment switcher</strong> — Footer control refined for clearer active profile / database selection and Manage access.</li><li><strong>Shared request editors</strong> — HTTP Client and Method Executor share the Params/Headers key-value editor for consistent Advanced editing.</li><li><strong>Keep-only gesture</strong> — Shift+click a trash action in field mappings, variables, named lists, request history, favourites, or key/value rows to retain that item and remove its siblings after confirmation.</li></ul><h3 id="docs-1" tabindex="-1">Docs <a class="header-anchor" href="#docs-1" aria-label="Permalink to &quot;Docs&quot;">​</a></h3><ul><li>Guide pages for <a href="https://midrissi.github.io/4d-dataexplorer/guide/console.html" target="_blank" rel="noreferrer">Console</a>, <a href="https://midrissi.github.io/4d-dataexplorer/guide/terminal.html" target="_blank" rel="noreferrer">ORDA Terminal</a>, <a href="https://midrissi.github.io/4d-dataexplorer/guide/rest-export.html" target="_blank" rel="noreferrer">REST Export</a>, <a href="https://midrissi.github.io/4d-dataexplorer/guide/environments.html" target="_blank" rel="noreferrer">Environment variables</a>, <a href="https://midrissi.github.io/4d-dataexplorer/guide/trusted-folders.html" target="_blank" rel="noreferrer">Trusted folders</a>, <a href="https://midrissi.github.io/4d-dataexplorer/guide/selection-tools.html" target="_blank" rel="noreferrer">Selection tools</a>, and <a href="https://midrissi.github.io/4d-dataexplorer/guide/mobile.html" target="_blank" rel="noreferrer">Mobile apps</a>.</li><li>Home gallery includes the Environment editor and updated screenshots (including light / dark captures).</li></ul><h3 id="fixes-1" tabindex="-1">Fixes <a class="header-anchor" href="#fixes-1" aria-label="Permalink to &quot;Fixes&quot;">​</a></h3><ul><li><strong>iOS downloads</strong> — Snippet and settings exports use the native download/share path instead of <code>&lt;a download&gt;</code> (NSURLError -3000).</li><li><strong>Dock tab restore</strong> — Reloading with Terminal open no longer forces Console.</li><li><strong>Entity reveal</strong> — Opening an entity from the terminal uses primary-key lookup instead of <code>$filter</code> on <code>__KEY</code>.</li><li><strong>Empty query params</strong> — Collection export disables empty <code>$filter</code> / <code>$orderby</code> / <code>$attributes</code> by default so they are not sent until filled in.</li><li><strong>OpenAPI responses</strong> — Exported specs list known 4D REST statuses (200, 401, 402, 404, 500).</li><li><strong>Request Docs tab</strong> — Request documentation includes the official 4D REST page markdown, not only a short summary.</li><li><strong>Dynamic name / range filters</strong> — Gender and numeric / date bounds on <code>$faker.*</code> templates resolve through Faker options.</li><li><strong>Faker <code>userName</code> alias</strong> — Field suggestions and templates accept the Faker v8 <code>internet.userName</code> name as an alias of <code>internet.username</code>.</li><li><strong>Docs templates</strong> — Environment guide and home copy render <code>{{…}}</code> examples without breaking the VitePress Vue compiler.</li><li><strong>Method Executor stale results</strong> — Failed or cancelled runs no longer leave a previous success visible under the config pane; errors replace the result view.</li><li><strong>Pending network body</strong> — Console network entries no longer wait for completion before showing the outgoing request body.</li></ul><h2 id="_1-3-x" tabindex="-1">1.3.x <a class="header-anchor" href="#_1-3-x" aria-label="Permalink to &quot;1.3.x&quot;">​</a></h2><h3 id="overview-2" tabindex="-1">Overview <a class="header-anchor" href="#overview-2" aria-label="Permalink to &quot;Overview&quot;">​</a></h3><p>Version <code>1.3.x</code> introduces Data Explorer Desktop (Tauri + React) with persistent connection profiles, native window integration, and in-app auto-updates; adds a Method Executor for selecting and running exposed ORDA methods with typed arguments and specialized result views; adds an HTTP Client for composing and replaying REST requests; adds a resizable Console panel that logs application messages and every HTTP request; improves cross-platform connection handling with HTTP fetch support; extends binary data handling with deferred BLOB loading; optimizes structure graph rendering for large schemas; and refines assistant feedback and accessibility in key navigation surfaces.</p><h3 id="features-2" tabindex="-1">Features <a class="header-anchor" href="#features-2" aria-label="Permalink to &quot;Features&quot;">​</a></h3><h4 id="desktop-app" tabindex="-1">Desktop app <a class="header-anchor" href="#desktop-app" aria-label="Permalink to &quot;Desktop app&quot;">​</a></h4><ul><li><strong>Data Explorer Desktop</strong> - New desktop application built with Tauri and React.</li><li><strong>Saved connections</strong> - Create, edit, and reuse connection profiles from a dedicated desktop connection screen.</li><li><strong>Window and theme handling</strong> - Better desktop startup behavior with improved window state and theme synchronization.</li><li><strong>Auto-updater</strong> - In-app update detection and process management with update notifications.</li><li><strong>macOS release pipeline</strong> - GitHub Actions workflow now packages and uploads macOS desktop artifacts.</li></ul><h4 id="method-executor-1" tabindex="-1">Method Executor <a class="header-anchor" href="#method-executor-1" aria-label="Permalink to &quot;Method Executor&quot;">​</a></h4><ul><li><strong>Method Executor tab</strong> - Configure and run exposed 4D methods from a dedicated tab; open from the command palette, dataclass and entity views, or the assistant.</li><li><strong>Scoped method calls</strong> - Call datastore, dataclass, entity, and entity-selection methods with ORDA-style expressions (<code>ds.method</code>, <code>ds.Table.method</code>, <code>ds.Table.entity(key).method</code>, <code>ds.Table.sel(key).method</code>).</li><li><strong>Runtime arguments</strong> - Build positional arguments as custom values, entity references, or entity selections; reorder, duplicate, and validate before execute.</li><li><strong>Run history</strong> - Reopen recent successful runs; ⌘/Ctrl+click keys in history to open the related entity or selection.</li><li><strong>Result views</strong> - Inspect JSON results, or open specialized entity and entity-selection previews automatically.</li></ul><h4 id="console-panel" tabindex="-1">Console panel <a class="header-anchor" href="#console-panel" aria-label="Permalink to &quot;Console panel&quot;">​</a></h4><ul><li><strong>Docked console</strong> - Open a resizable bottom panel from the status bar or the command palette to inspect logs while browsing.</li><li><strong>Network logging</strong> - Every HTTP request is recorded with method, URL, status, duration, and response size; expand an entry to inspect headers and bodies (secrets redacted).</li><li><strong>Open in HTTP Client</strong> - Replay a captured network entry in the HTTP Client with sanitized method, URL, headers, and body when available.</li><li><strong>Filters and controls</strong> - Filter by level (all, log, info, warn, error, network), collapse all expanded rows, and clear the in-memory buffer; error and warning counts appear on the footer Console button.</li></ul><h4 id="http-client" tabindex="-1">HTTP Client <a class="header-anchor" href="#http-client" aria-label="Permalink to &quot;HTTP Client&quot;">​</a></h4><ul><li><strong>HTTP Client tab</strong> - Compose and send HTTP requests from Tools or the command palette against the current server or a custom origin.</li><li><strong>Request editor</strong> - Method, server, and path autocomplete; Params, Headers, Body (none / form / urlencoded / raw / binary), and Settings.</li><li><strong>Response inspector</strong> - Status, timing, size, headers, cookies, and body after Send (⌘/Ctrl+Enter).</li><li><strong>Desktop options</strong> - Cookie session control, timeouts, redirect limits, and optional TLS skip on desktop builds.</li></ul><h4 id="connectivity-data-loading" tabindex="-1">Connectivity &amp; data loading <a class="header-anchor" href="#connectivity-data-loading" aria-label="Permalink to &quot;Connectivity &amp; data loading&quot;">​</a></h4><ul><li><strong>HTTP fetch support</strong> - Connection flows were updated to support fetch-based HTTP calls across environments.</li><li><strong>Deferred BLOB loading</strong> - Binary object loading is improved with on-demand BLOB retrieval in the entity viewer.</li></ul><h4 id="structure-graph-ui" tabindex="-1">Structure graph &amp; UI <a class="header-anchor" href="#structure-graph-ui" aria-label="Permalink to &quot;Structure graph &amp; UI&quot;">​</a></h4><ul><li><strong>Graph responsiveness</strong> - Dataclass graph rendering now uses card-dimension estimation and optimized node highlight comparisons.</li><li><strong>Assistant activity feedback</strong> - Chatbot responses now show clearer loading states and an animated sparkles indicator.</li><li><strong>Accessibility improvements</strong> - Sidebar, tab bar, command palette, and related views received accessibility and semantic class-name refinements.</li></ul><h3 id="fixes-2" tabindex="-1">Fixes <a class="header-anchor" href="#fixes-2" aria-label="Permalink to &quot;Fixes&quot;">​</a></h3><ul><li><strong>Binary object rendering</strong> - Improved deferred binary handling paths in the entity viewer.</li><li><strong>Connection editing stability</strong> - Desktop connection edit/update flows were stabilized.</li><li><strong>Coverage HTML layout</strong> - Adjusted padding in generated coverage HTML output for cleaner rendering.</li></ul><h2 id="_1-2-x" tabindex="-1">1.2.x <a class="header-anchor" href="#_1-2-x" aria-label="Permalink to &quot;1.2.x&quot;">​</a></h2><h3 id="overview-3" tabindex="-1">Overview <a class="header-anchor" href="#overview-3" aria-label="Permalink to &quot;Overview&quot;">​</a></h3><p>Version <code>1.2.x</code> adds a visual field manager for displayed attributes (including nested relation paths), inline on-demand loading of related entities, a grouped metadata panel, a binary object viewer, ORDA language assistance in the query builder, an AI assistant with configurable tools, a JSON Schema Builder, Monaco-based code editors, entity set management in the query builder, the Assistant Metadata Editor, bulk entity mutations, access key authentication, structure graph enhancements including fit-to-view navigation, entity viewer loading and error states, and UI improvements across the assistant and query builder.</p><h3 id="features-3" tabindex="-1">Features <a class="header-anchor" href="#features-3" aria-label="Permalink to &quot;Features&quot;">​</a></h3><h4 id="display-fields" tabindex="-1">Display fields <a class="header-anchor" href="#display-fields" aria-label="Permalink to &quot;Display fields&quot;">​</a></h4><ul><li><strong>Field manager</strong> — Choose and reorder the attributes shown in table columns and cards from a single popover; selections are kept per tab.</li><li><strong>Nested attributes</strong> — Drill into relations to select nested attributes (e.g. <code>company.name</code>, and deeper) for both table and card views.</li><li><strong>Per-view selection</strong> — Maintain independent attribute lists for the table and card views; drag to reorder.</li><li><strong>Save as default</strong> — Save the current selection as the default for a dataclass, or reset back to defaults.</li></ul><h4 id="entity-viewer" tabindex="-1">Entity viewer <a class="header-anchor" href="#entity-viewer" aria-label="Permalink to &quot;Entity viewer&quot;">​</a></h4><ul><li><strong>Deferred relations</strong> — Load related entities and related entity sets on demand, inline in the form and tree views.</li><li><strong>Shared table for relations</strong> — Related entity sets render in the same data grid used by the table view.</li><li><strong>Metadata panel</strong> — 4D system attributes (<code>__KEY</code>, <code>__STAMP</code>, <code>__TIMESTAMP</code>, …) are grouped into a collapsible metadata panel.</li><li><strong>All attributes in details</strong> — The details view always shows every attribute, even when the field manager limits the columns or fields in the list.</li><li><strong>Expandable card fields</strong> — Cards preview the first fields with a Show more / Show less toggle.</li><li><strong>Binary object viewer</strong> — Preview 4D private binary objects (blobs and pictures) directly in the entity form and viewer.</li><li><strong>Loading indicators</strong> — Entity data shows a loading state while fetching, including related entities and entity sets.</li><li><strong>Error recovery</strong> — When entities fail to load, an inline panel lets you try again, reset the query, or close the tab.</li><li><strong>Deferred images</strong> — Picture attributes load on demand in table cells and the entity viewer.</li><li><strong>Cell tooltips</strong> — Hover truncated table cells to reveal the full value.</li><li><strong>Column sorting</strong> — Sort entity tables by column, including related entity tables.</li></ul><h4 id="assistant-metadata-editor" tabindex="-1">Assistant Metadata Editor <a class="header-anchor" href="#assistant-metadata-editor" aria-label="Permalink to &quot;Assistant Metadata Editor&quot;">​</a></h4><ul><li><strong>Metadata Editor tab</strong> — Document dataclasses, attributes, methods, singletons, and catalog methods for the AI assistant; open from Tools, the command palette, or the assistant toolbar.</li><li><strong>AI description generation</strong> — Generate descriptions per field or in bulk for all missing entries; optional JSON Schema generation for method parameters.</li><li><strong>Missing-description indicators</strong> — Highlight items without documentation; filter the sidebar to show only missing entries.</li><li><strong>JSON editor</strong> — Edit the full metadata object directly; export the schema as a JSON file.</li></ul><h4 id="ai-assistant" tabindex="-1">AI Assistant <a class="header-anchor" href="#ai-assistant" aria-label="Permalink to &quot;AI Assistant&quot;">​</a></h4><ul><li><strong>Assistant panel</strong> — AI chat panel with tools to query data, navigate tabs, run commands, and control the UI.</li><li><strong>Configurable tools</strong> — Enable or disable assistant tool namespaces and individual tools in Settings.</li><li><strong>Fullscreen mode</strong> — Expand the assistant panel to fill the screen; press Escape to exit.</li><li><strong>Copy trace</strong> — Copy the assistant activity trace to the clipboard from the activity panel.</li><li><strong>Mermaid diagrams</strong> — Improved rendering and error handling for Mermaid charts in assistant responses.</li></ul><h4 id="data-operations" tabindex="-1">Data operations <a class="header-anchor" href="#data-operations" aria-label="Permalink to &quot;Data operations&quot;">​</a></h4><ul><li><strong>Bulk entity create/update</strong> — Create or update multiple entities in one call via the API and assistant datastore tools.</li></ul><h4 id="json-schema-builder" tabindex="-1">JSON Schema Builder <a class="header-anchor" href="#json-schema-builder" aria-label="Permalink to &quot;JSON Schema Builder&quot;">​</a></h4><ul><li><strong>Schema Builder tab</strong> — Visual editor for building JSON schemas; open from the Tools menu in the footer.</li><li><strong>Object editor</strong> — Expand or collapse nested objects and configure schema attributes.</li></ul><h4 id="code-editor" tabindex="-1">Code editor <a class="header-anchor" href="#code-editor" aria-label="Permalink to &quot;Code editor&quot;">​</a></h4><ul><li><strong>Monaco editor</strong> — Code and JSON editors with schema completion throughout the app.</li><li><strong>Editor preferences</strong> — Configure font size, word wrap, and toolbar in Settings; applies to entity forms, the schema builder, and other editors.</li></ul><h4 id="query-entity-sets" tabindex="-1">Query &amp; entity sets <a class="header-anchor" href="#query-entity-sets" aria-label="Permalink to &quot;Query &amp; entity sets&quot;">​</a></h4><ul><li><strong>ORDA language assistance</strong> — Code completion, hover information, and signature help for ORDA query expressions, with type resolution against the catalog.</li><li><strong>Entity set operations</strong> — Combine entity sets (<code>AND</code> / <code>OR</code> / <code>EXCEPT</code> / <code>INTERSECT</code>) and release entity sets via the API and assistant tools.</li><li><strong>Entity set binding</strong> — Bind dataclass tabs to existing server entity set IDs; load, copy, and edit entity set IDs in the query builder.</li><li><strong>Entity set caching</strong> — Server-side entity sets are cached and released when tabs close.</li><li><strong>Filter parameters</strong> — Define typed filter parameters for parameterized filter expressions in the query builder.</li></ul><h4 id="profiles-appearance" tabindex="-1">Profiles &amp; appearance <a class="header-anchor" href="#profiles-appearance" aria-label="Permalink to &quot;Profiles &amp; appearance&quot;">​</a></h4><ul><li><strong>Quick profile switch</strong> — Switch profiles from the footer without opening Settings; profile icon and color shown in the status bar.</li><li><strong>Per-profile appearance</strong> — Customize each profile with an icon and color.</li><li><strong>Qodly theme</strong> — New Qodly color theme with light and dark modes (Roboto typography, purple accent).</li></ul><h4 id="structure-graph" tabindex="-1">Structure graph <a class="header-anchor" href="#structure-graph" aria-label="Permalink to &quot;Structure graph&quot;">​</a></h4><ul><li><strong>Method signatures</strong> — Method signatures highlighted in the structure graph.</li><li><strong>Attribute indicators</strong> — Exposed attributes and relation handles visually highlighted on dataclass nodes.</li><li><strong>Stable navigation</strong> — Repeated dataclass clicks no longer clear the graph; viewport is validated and node selection is preserved.</li><li><strong>Fit to view</strong> — Recenter and zoom the structure graph to fit all visible nodes.</li></ul><h4 id="authentication-localization" tabindex="-1">Authentication &amp; localization <a class="header-anchor" href="#authentication-localization" aria-label="Permalink to &quot;Authentication &amp; localization&quot;">​</a></h4><ul><li><strong>Access key login</strong> — Sign in with a REST access key when the server requires authentication.</li><li><strong>Internationalization</strong> — Expanded translations across the assistant UI, query builder, and other components.</li></ul><h3 id="fixes-3" tabindex="-1">Fixes <a class="header-anchor" href="#fixes-3" aria-label="Permalink to &quot;Fixes&quot;">​</a></h3><ul><li><strong>Tab state</strong> — Per-tab state stays consistent when switching tabs (active tab synchronization); the active tab ID is validated before closing tabs or setting entity set IDs.</li><li><strong>Profile shortcuts</strong> — Shortcuts are merged with defaults when loading profiles so empty shortcut lists no longer wipe configured shortcuts.</li><li><strong>Structure graph viewport</strong> — Programmatic pan/zoom no longer corrupts saved viewport state.</li><li><strong>List view editing</strong> — Disabled in-table editing in list view to prevent accidental edits.</li><li><strong>Tab activation order</strong> — Closing a tab now activates the most recently used tab instead of the adjacent one.</li></ul><hr><h2 id="_1-1-x" tabindex="-1">1.1.x <a class="header-anchor" href="#_1-1-x" aria-label="Permalink to &quot;1.1.x&quot;">​</a></h2><h3 id="overview-4" tabindex="-1">Overview <a class="header-anchor" href="#overview-4" aria-label="Permalink to &quot;Overview&quot;">​</a></h3><p>Version <code>1.1.x</code> delivers a refined 4D REST Explorer for browsing dataclasses and entities, with profile management, a global search bar, command-palette quick modes, keyboard shortcut refinements, language selection, and a focused set of capabilities for viewing and editing data.</p><h3 id="features-4" tabindex="-1">Features <a class="header-anchor" href="#features-4" aria-label="Permalink to &quot;Features&quot;">​</a></h3><h4 id="home-navigation" tabindex="-1">Home &amp; Navigation <a class="header-anchor" href="#home-navigation" aria-label="Permalink to &quot;Home &amp; Navigation&quot;">​</a></h4><ul><li><strong>Welcome screen</strong> — Summary of your database: stats, entity counts, and charts (<code>bar</code> and <code>pie</code>)</li><li><strong>Global search bar</strong> — Search bar in the header; click or focus to open the command palette.</li><li><strong>Command palette</strong> — Open entities by ID, open a dataclass, or search dataclasses from one place</li><li><strong>Recent commands</strong> — Recently used commands appear at the top of the palette with a clock icon; history is stored per profile.</li><li><strong>Quick modes</strong> — From the palette search, type <code>:</code> to jump to an entity by index, <code>&gt;</code> to pick a dataclass for the structure view, <code>/</code> to open a dataclass’s data, or <code>@</code> to switch between tabs.</li><li><strong>Keyboard shortcuts</strong> — Custom shortcuts for common actions (<code>command palette</code>, <code>settings</code>, <code>theme</code>, <code>structure</code>, etc.)</li><li><strong>Tabbed interface</strong> — Pin tabs, close others, or reorder by dragging</li><li><strong>Release notes tab</strong> — Open release notes from the status bar (footer); content is shown in a dedicated tab</li><li><strong>Language</strong> — Choose app language (English, French, Spanish) from the status bar (footer); release notes and UI follow the selected language.</li></ul><h4 id="dataclass-entities" tabindex="-1">Dataclass &amp; Entities <a class="header-anchor" href="#dataclass-entities" aria-label="Permalink to &quot;Dataclass &amp; Entities&quot;">​</a></h4><ul><li><strong>Dataclass browser</strong> — Work with several dataclasses in tabs and switch between card and table layout</li><li><strong>Query builder</strong> — Apply filter, sort, field selection, and limit; collapsible query panel</li><li><strong>Entity list</strong> — Paginated list in a resizable panel with entity count badges</li><li><strong>Entity viewer</strong> — Inspect entity <code>JSON</code> and create, edit, or delete entities (unless read-only is on)</li><li><strong>Go to entity</strong> — Open a given entity by ID from the command palette</li></ul><h4 id="structure-visualization" tabindex="-1">Structure &amp; Visualization <a class="header-anchor" href="#structure-visualization" aria-label="Permalink to &quot;Structure &amp; Visualization&quot;">​</a></h4><ul><li><strong>Structure graph</strong> — Diagram of dataclasses and their links; highlight a dataclass from the tab context menu</li><li><strong>Dataclass appearance</strong> — Per-dataclass colors and icons in Settings</li></ul><h4 id="profiles-settings" tabindex="-1">Profiles &amp; settings <a class="header-anchor" href="#profiles-settings" aria-label="Permalink to &quot;Profiles &amp; settings&quot;">​</a></h4><ul><li><strong>Profile management</strong> — Create, rename, duplicate, and delete profiles in Settings. Each profile has its own theme, shortcuts, sidebar width, and other preferences.</li><li><strong>Import / export</strong> — Export all settings or selected profiles to a JSON file, and import settings or profiles from a file (with the option to choose which profiles to import).</li></ul><h4 id="settings-appearance" tabindex="-1">Settings &amp; Appearance <a class="header-anchor" href="#settings-appearance" aria-label="Permalink to &quot;Settings &amp; Appearance&quot;">​</a></h4><ul><li><strong>Appearance</strong> — Several color themes (<code>Slate</code>, <code>Tangerine</code>, <code>Violet Bloom</code>, <code>Graphite</code>, <code>Aurora</code>, etc.)</li><li><strong>Light / dark mode</strong> — Follow system or switch manually</li><li><strong>Default views</strong> — Choose default layout (<code>cards</code> or <code>table</code>) and page size for new dataclass tabs</li><li><strong>Keyboard shortcuts</strong> — Turn shortcuts on or off and see the full list in Settings</li><li><strong>Dataclass appearance</strong> — Set colors and icons for each dataclass in the sidebar and tabs</li></ul><h4 id="keyboard-shortcuts" tabindex="-1">Keyboard shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard shortcuts&quot;">​</a></h4><ul><li><strong>Shortcuts modal</strong> — The &quot;View&quot; section is now shown in two columns for a more compact layout.</li><li><strong>Record as chord</strong> — The &quot;Record as chord (two-key sequence)&quot; option is now in the shortcut record modal, so you can choose chord mode when recording a shortcut.</li><li><strong>Shortcut display</strong> — Shortcut buttons in Settings use a lighter, border-only style (no background) for the key labels.</li></ul><h4 id="safety-modes" tabindex="-1">Safety &amp; Modes <a class="header-anchor" href="#safety-modes" aria-label="Permalink to &quot;Safety &amp; Modes&quot;">​</a></h4><ul><li><strong>Read-only mode</strong> — Header toggle to turn off create/edit/delete for safe browsing</li><li><strong>Edit mode</strong> — Create, update, and delete entities when enabled</li></ul><h3 id="technical" tabindex="-1">Technical <a class="header-anchor" href="#technical" aria-label="Permalink to &quot;Technical&quot;">​</a></h3><ul><li><strong>4D REST API</strong> — Talks to your 4D server over REST and supports standard query parameters</li><li><strong>Persistent state</strong> — Tabs, sidebar width, and settings are stored per base (<code>BASEID</code>)</li></ul>',123)])])}const p=t(s,[["render",i]]);export{u as __pageData,p as default};
